/*
 * A287769  {0->1, 1->110}-transform of the infinite Fibonacci word A003849.
 * https://oeis.org/A287769
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = floor((n+1)*r) - floor(n*r), where r = (15 + sqrt(5))/22.
 *            The sequence is generated by applying the morphism 0 → 1, 1 →
 *            110 to the infinite Fibonacci word A003849
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Includes */
#include <stdlib.h>
#include <stddef.h>

/* Helper prototypes for arbitrary‑precision builds */
#ifndef HAVE_SEQ_ALLOC
/* If seq_alloc_new_array / seq_realloc are not available,
   fall back to malloc/realloc.  The build system
   supplies these for big‑integer configurations. */
#define seq_alloc_new_array(n) ((seq_t*)malloc((n)*sizeof(seq_t)))
#define seq_realloc(ptr, oldcap, newcap) ((seq_t*)realloc((ptr), (newcap)*sizeof(seq_t)))
#endif

/* Static storage for generated terms and input bits of the
   Fibonacci word (prefix).  All indices are 0‑based. */
static seq_t *cache   = NULL;     /* computed a(n) values (size: cache_len) */
static size_t cache_len = 0;      /* number of terms in cache */
static size_t cache_cap = 0;      /* allocated size of cache */

static unsigned char *fib_bits = NULL; /* prefix of the Fibonacci word */
static size_t fib_len = 0;          /* number of bits in fib_bits */
static size_t fib_cap = 0;          /* allocated size of fib_bits */

static size_t fib_map_pos = 0;      /* position in fib_bits used for mapping */

/* Extend fib_bits by one substitution step:
   0 -> 01   (length 2)
   1 -> 0    (length 1) */
static void extend_fib(void)
{
    size_t new_len = 0;
    for (size_t i = 0; i < fib_len; ++i)
        new_len += (fib_bits[i] == 0) ? 2 : 1;

    unsigned char *new_bits;
    if (fib_cap < new_len) {
        new_bits = (unsigned char*)malloc(new_len);
        fib_cap = new_len;
    } else {
        new_bits = fib_bits;
    }

    size_t j = 0;
    for (size_t i = 0; i < fib_len; ++i) {
        if (fib_bits[i] == 0) {      /* 0 -> 01 */
            new_bits[j++] = 0;
            new_bits[j++] = 1;
        } else {                      /* 1 -> 0 */
            new_bits[j++] = 0;
        }
    }

    fib_len = new_len;
    if (new_bits != fib_bits) {
        free(fib_bits);
        fib_bits = new_bits;
    }
}

/* Ensure that cache contains at least n terms (n ≥ 1). */
static void ensure_cache(idx_t n)
{
    if (n == 0) return;          /* undefined per offset; ignore */
    size_t target = (size_t)n;   /* n fits into size_t for the use cases */

    /* Lazy initialization of the Fibonacci word prefix.  The
       first word is simply "0". */
    if (fib_len == 0) {
        fib_cap = 1;
        fib_bits = (unsigned char*)malloc(1);
        fib_bits[0] = 0;
        fib_len = 1;
        fib_map_pos = 0;
    }

    /* Grow the cache while it holds fewer than target terms. */
    while (cache_len < target) {
        /* If we have exhausted the current Fibonacci prefix,
           generate the next substitution level. */
        if (fib_map_pos == fib_len)
            extend_fib();

        /* Map the next input bit to output bits. */
        unsigned char bit = fib_bits[fib_map_pos++];
        if (bit == 0) {
            /* 0 -> 1 */
            if (cache_len + 1 > cache_cap) {
                size_t new_cap = cache_cap > 0 ? cache_cap * 2 : 1;
                while (new_cap < cache_len + 1) new_cap *= 2;
                cache = seq_realloc(cache, cache_cap, new_cap);
                cache_cap = new_cap;
            }
            cache[cache_len++] = 1;
        } else {
            /* 1 -> 1 1 0 (three bits) */
            size_t needed = cache_len + 3;
            if (needed > cache_cap) {
                size_t new_cap = cache_cap > 0 ? cache_cap * 2 : 1;
                while (new_cap < needed) new_cap *= 2;
                cache = seq_realloc(cache, cache_cap, new_cap);
                cache_cap = new_cap;
            }
            cache[cache_len++] = 1;
            cache[cache_len++] = 1;
            cache[cache_len++] = 0;
        }
    }
}

/* Public sequence function. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;      /* undefined per offset; guard against underflow */
    ensure_cache(n);
    return cache[(size_t)n - 1];
}
